              finance='SELECT branch_id, first_name, last_name, salary,\n       ROW_NUMBER() OVER (PARTITION BY branch_id ORDER BY salary DESC, employee_id) AS rank_in_branch\nFROM employees\nWHERE branch_id IS NOT NULL\nORDER BY branch_id, rank_in_branch;',
